// 数据参考自 cnpoe.com/poe2/regex 正则工坊，并对照 poe2db.tw 校正分类。
class Poe2RegexItem {
  final String id;
  final String label;
  final String cn;
  final String? tc;
  final String group;
  final String category;
  const Poe2RegexItem({
    required this.id,
    required this.label,
    required this.cn,
    this.tc,
    this.group = '',
    this.category = '',
  });
  bool get isCustom => category.isNotEmpty;
  Map<String, dynamic> toJson() => {'id': id, 'label': label, 'cn': cn, 'tc': tc ?? '', 'group': group, 'category': category};
  factory Poe2RegexItem.fromJson(Map<String, dynamic> json) => Poe2RegexItem(
    id: json['id'] as String? ?? '',
    label: json['label'] as String? ?? '',
    cn: json['cn'] as String? ?? '',
    tc: (json['tc'] as String?)?.isEmpty == true ? null : json['tc'] as String?,
    group: json['group'] as String? ?? '',
    category: json['category'] as String? ?? '',
  );
}

